def cleanup_existing_expired_pending_jobs(apps, schema_editor):
    Job = apps.get_model('jobs', 'Job')
    SkippedRecruitment = apps.get_model('jobs', 'SkippedRecruitment')
    from django.utils import timezone
    today = timezone.now().date()

    expired_pending = Job.objects.filter(status='pending_review', application_deadline__lt=today)
